"""Commented source ownership of the shared ALL/BUT parser state."""
import sys,json
from pathlib import Path
sys.dont_write_bytecode=True
p=Path(__file__).resolve().parents[2];sys.path.insert(0,str(p/'skoolkit-10.1'))
from skoolkit.traceutils import disassemble
from skoolkit.z80 import Assembler
m=bytes(0x5d80)+(p/'sherlock-analisi/block-10.bin').read_bytes();asm=Assembler()
regions=[(0xA01A,0xA01B,'data','Stato condiviso ALL/BUT dell’unità di parsing'),(0xAAB2,0xAABD,'code','Ingresso del parser: reset di ALL/BUT e contatore'),(0xACA6,0xACCC,'code','Copia nominale: BUT conserva lo slot fisico corrente'),(0xACCC,0xAD6C,'code','Coordinazioni e backtracking: esclusioni condivise e conteggio'),(0xAE11,0xAE1E,'code','Eredità del verbo: applicata nella post-elaborazione riuscita'),(0xAEF1,0xAF04,'code','Copia del verbo omesso senza propagare il bit ALL'),(0xAF67,0xAF6B,'code','Errore sintattico: ritorno senza cancellare ALL/BUT'),(0xAFE8,0xAFFA,'code','Condizioni di ALL: verbo, contatore e chiarimento pendente'),(0xB01C,0xB049,'code','Transizioni ALL=1 e BUT=2; nessuna ripetizione nella stessa unità'),(0xD835,0xD870,'code','Fine di ALL: rilascio delle esclusioni e fallimento prima del nodo seguente')]
notes={0xACA6:'I bit6/7 di E indicano quale slot nominale è ancora disponibile. B026 alloca un nodo ma non azzera questi bit: BUT dopo un primo gruppo scrive nel secondo slot del nuovo nodo.',0xACB2:'Se anche il secondo slot è già consumato, ritorna Z: un ulteriore gruppo nominale è un errore, non un terzo campo oltre il record.',0xAE19:'Eredità solo dopo il parsing riuscito. Un verbo assunto per comodità dal modello semantico non deve finire nel payload del nodo liberato dopo un errore precedente.',0xAEF5:'Maschera il bit7 ALL del verbo precedente; il nuovo nodo non diventa un altro ALL.',0xD835:'Il nodo ordinario e la coda di esclusioni vengono rimossi insieme quando la ricerca corrente è finita.',0xD86A:'Esaurimento di ALL: libera il nodo, poi DC15 restituisce fallimento. Se rimane un nodo ordinario nella stessa unità, il tentativo fallito viene contato prima di eseguirlo.',0xA01A:'Byte iniziale00. AAB3 scrive0 soltanto quando entra davvero nel parser; B03F scrive1 dopo ALL; B026 scrive2 dopo BUT. Non è il bit ALL dell’ultimo nodo AST.',0xAAB3:'Nuova unità: ALL/BUT=0, anche dopo il rinvio di un nuovo verbo e quando entra nel parsing di una citazione. Un errore lessicale precedente non raggiunge questo reset.',0xACEB:'Salva A012 per il backtracking. Non salva A01A: i due stati hanno cicli di vita distinti.',0xACEE:'Se A01A=2, il nodo attraversato da questa coordinazione è un’esclusione anche se il nodo precedente è stato sostituito.',0xAD3D:'Ripristina il conteggio speculativo A012, non lo stato ALL/BUT.',0xAD57:'Con A01A=2 il separatore A0 salta AD66; la chiusura finale conta invece anche l’esclusione.',0xAF67:'Errore sintattico: A01A conserva l’ultima scrittura. Non ripristinarlo dal nodo finale o azzerarlo nella gestione generale degli errori.',0xAFE8:'ALL verifica il bit di presenza del verbo. Se manca, sono ammesse solo la prima costruzione e una precisazione pendente: gli altri casi tornano ad AF67.',0xAFF1:'Consulta A01B, cioè il chiarimento pendente, dopo aver verificato il conteggio A012.',0xB01C:'BUT richiede lo stato condiviso1, non il booleano ALL del nodo corrente.',0xB026:'Passa a2 prima dell’allocazione del nuovo nodo esclusione. Un errore nominale successivo conserva2.',0xB033:'Il controllo AFE8 precede la verifica dello stato: non scrivere ALL=1 prima di aver superato entrambi.',0xB036:'ALL è ammesso solo con stato0. Dopo AND lo stato resta condiviso finché non viene avviata una nuova unità.',0xB03F:'Transizione a1; il bit7 del nodo è una seconda informazione distinta, usata dall’esecuzione collettiva.'}
lines=['; Analisi offline, dati distinti dal codice; nessuna esecuzione Z80 nel motore JS.'];count=total=0
for a,b,kind,label in regions:
 lines+=['',f'    ORG ${a:04X}',f'; {kind.upper()}: {label}'];at=a
 while at<b:
  if kind=='data':n=b-at;op='DEFB '+','.join(f'${v:02X}'for v in m[at:b])
  else:op,n=disassemble(m,at);count+=1
  assert at+n<=b,(hex(at),op);assert bytes(asm.assemble(op,at))==m[at:at+n]
  lines.append(f'    {op:<37} ; ${at:04X} {m[at:at+n].hex(" ")}'+(' | '+notes[at]if at in notes else''));at+=n;total+=n
root=p/'sherlock-js/results/parser-all';root.mkdir(exist_ok=True)
(root/'parser-all.asm').write_text('\n'.join(lines)+'\n')
(root/'listing-verification.json').write_text(json.dumps(dict(roundtrip_equal=True,instructions=count,bytes_roundtripped=total,regions=[dict(start=f'{a:04X}',end_exclusive=f'{b:04X}',kind=k,label=l,atlas_priority=122 if k=='data'else 92,**({'fields':[['A01A','1','0 nessuno; 1 ALL; 2 BUT. Persistenza su errore e reset solo a ingresso AAB2'],['Distinto da','bit7/bit6 dei nodi','Non inferire lo stato dall’AST finale: coordinazioni e backtracking hanno effetti propri']]}if k=='data'else{}))for a,b,k,l in regions]),indent=2)+'\n');print(count,total)
